PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?song ?date WHERE {
  VALUES ?song { dbr:Wherever_I_Lay_My_Hat_(That's_My_Home) dbr:Don't_Ya }
  OPTIONAL { ?song dbo:recordDate ?date1 . }
  OPTIONAL { ?song dbp:year ?date2 . }
  BIND (COALESCE(?date1, ?date2) AS ?date)
}
LIMIT 100

